use vstd::prelude::*;

verus! {
    /// Insert `value` into vector `arr` at position `idx`,
    /// shifting later elements one slot to the right.
    pub fn numpy_insert<T>(arr: Vec<T>, idx: usize, value: T) -> Vec<T>
        requires
            // idx is in [0, arr.len()]
            idx <= arr.len(),
        ensures
            // The result is exactly one longer than the original.
            result.len() == arr.len() + 1,
        ensures
            // Elements before `idx` are unchanged.
            forall |j: usize| j < idx ==>
                result[j] == arr[j],
        ensures
            // The inserted element appears at position `idx`.
            result[idx] == value,
        ensures
            // Original elements at positions ≥ idx are shifted right by one.
            forall |j: usize| idx <= j && j < arr.len() ==>
                result[j + 1] == arr[j],
    {
        // Pre‐allocate the new vector to the correct final size.
        let mut result = Vec::with_capacity(arr.len() + 1);

        // Move the first `idx` elements over unchanged.
        let mut into_iter = arr.into_iter();
        for _ in 0..idx {
            // Safe because idx <= arr.len()
            let x = into_iter.next().unwrap();
            result.push(x);
        }

        // Insert the new value at position `idx`.
        result.push(value);

        // Move the remainder of the elements, shifting them right by one.
        for x in into_iter {
            result.push(x);
        }

        result
    }
}